namespace BatchRenameStudio.Core;

/// <summary>Rule 13, first clause: what makes a proposed name unusable on Windows.</summary>
public static class NameValidator
{
    public const int MaxNameLength = 255;

    private static readonly char[] ForbiddenChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedDeviceNames = BuildReservedNames();

    private static HashSet<string> BuildReservedNames()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "CON", "PRN", "AUX", "NUL" };
        for (int i = 1; i <= 9; i++)
        {
            set.Add("COM" + i);
            set.Add("LPT" + i);
        }

        return set;
    }

    /// <summary>Returns true when the name cannot be used; <paramref name="reason"/> explains why.</summary>
    public static bool IsInvalid(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "empty name";
            return true;
        }

        if (proposed.Length > MaxNameLength)
        {
            reason = $"longer than {MaxNameLength} characters";
            return true;
        }

        foreach (var ch in proposed)
        {
            if (ch < ' ')
            {
                reason = $"contains control character U+{(int)ch:X4}";
                return true;
            }

            if (Array.IndexOf(ForbiddenChars, ch) >= 0)
            {
                reason = $"contains forbidden character '{ch}'";
                return true;
            }
        }

        var baseName = SplitName.Split(proposed).Base;
        if (ReservedDeviceNames.Contains(baseName))
        {
            reason = $"'{baseName}' is a reserved device name";
            return true;
        }

        reason = string.Empty;
        return false;
    }
}

