/// <summary>One candidate file, reduced to the facts the planner needs. Keeps the planner testable.</summary>
public sealed record FileEntry(string Name, DateTime CreatedUtc, DateTime ModifiedUtc);

/// <summary>Turns a folder plus a rule set into a plan. Pure once the folder has been scanned.</summary>
public static class PlanBuilder
{
    /// <summary>Rule 1: regular files directly inside the folder, non-recursive, directories excluded.</summary>
    public static List<FileEntry> Scan(string directory)
    {
        var info = new DirectoryInfo(directory);
        if (!info.Exists) throw new DirectoryNotFoundException($"folder not found: {directory}");

        var entries = new List<FileEntry>();
        foreach (var file in info.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            if ((file.Attributes & FileAttributes.Directory) != 0) continue;
            entries.Add(new FileEntry(file.Name, file.CreationTimeUtc, file.LastWriteTimeUtc));
        }

        return entries;
    }

    /// <summary>
    /// Rule 5: ascending processing order. Timestamp sorts fall back to the ordinal name so that equal
    /// timestamps still yield one deterministic order (rule 15).
    /// </summary>
    public static List<FileEntry> Order(IEnumerable<FileEntry> files, SortMode sort) => sort switch
    {
        SortMode.Created => files.OrderBy(f => f.CreatedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
        SortMode.Modified => files.OrderBy(f => f.ModifiedUtc).ThenBy(f => f.Name, StringComparer.Ordinal).ToList(),
        _ => files.OrderBy(f => f.Name, StringComparer.Ordinal).ToList(),
    };

    public static RenamePlan Build(string directory, RuleSet rules) =>
        Build(Scan(directory), rules);

    public static RenamePlan Build(IEnumerable<FileEntry> files, RuleSet rules)
    {
        NameTransformer.ValidateRegexes(rules);

        var ordered = Order(files, rules.Sort);
        var proposed = new string[ordered.Count];
        for (int i = 0; i < ordered.Count; i++)
            proposed[i] = NameTransformer.Apply(rules, ordered[i].Name, i);

        // Index the originals and count the proposals, both case-insensitively (rule 13, collision clause).
        var originalIndex = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        for (int i = 0; i < ordered.Count; i++) originalIndex.TryAdd(ordered[i].Name, i);

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var name in proposed)
            proposedCounts[name] = proposedCounts.TryGetValue(name, out var c) ? c + 1 : 1;

        var plan = new RenamePlan();
        for (int i = 0; i < ordered.Count; i++)
        {
            var original = ordered[i].Name;
            var candidate = proposed[i];
            string status;
            string reason;

            if (NameValidator.IsInvalid(candidate, out var invalidReason))
            {
                status = PlanStatus.Invalid;
                reason = invalidReason;
            }
            else if (proposedCounts[candidate] > 1)
            {
                status = PlanStatus.Collision;
                reason = "another file is proposed the same name";
            }
            else if (originalIndex.TryGetValue(candidate, out var owner) && owner != i)
            {
                status = PlanStatus.Collision;
                reason = "an existing file already uses this name";
            }
            else if (string.Equals(candidate, original, StringComparison.Ordinal))
            {
                status = PlanStatus.Unchanged;
                reason = "name is unchanged";
            }
            else
            {
                status = PlanStatus.Ok;
                reason = string.Empty;
            }

            plan.Items.Add(new PlanItem
            {
                Original = original,
                Proposed = candidate,
                Status = status,
                Reason = reason,
            });
        }

        var summary = plan.Summary;
        summary.Total = plan.Items.Count;
        summary.Ok = plan.Items.Count(i => i.Status == PlanStatus.Ok);
        summary.Collision = plan.Items.Count(i => i.Status == PlanStatus.Collision);
        summary.Unchanged = plan.Items.Count(i => i.Status == PlanStatus.Unchanged);
        summary.Invalid = plan.Items.Count(i => i.Status == PlanStatus.Invalid);
        return plan;
    }
}

