namespace BatchRenameStudio.Core;

/// <summary>One completed rename, kept so it can be reversed.</summary>
public sealed record RenameRecord(string From, string To);

/// <summary>The reversible unit of work: everything one Apply did, in the order it happened.</summary>
public sealed class RenameJournal
{
    public required string Directory { get; init; }
    public List<RenameRecord> Records { get; } = new();
}

public sealed class RenameOutcome
{
    public RenameJournal Journal { get; init; } = new() { Directory = string.Empty };
    public List<string> Errors { get; } = new();
    public int RenamedCount => Journal.Records.Count;
}

/// <summary>
/// Performs the renames. Every batch goes through unique temporary names first, so cycles
/// (a -&gt; b, b -&gt; a) and chains succeed instead of colliding half way through.
/// </summary>
public static class RenameExecutor
{
    private const string TempMarker = ".brs-tmp-";

    public static RenameOutcome Apply(string directory, IEnumerable<PlanItem> items)
    {
        var work = items.Where(i => i.Status == PlanStatus.Ok).ToList();
        var outcome = new RenameOutcome { Journal = new RenameJournal { Directory = directory } };
        if (work.Count == 0) return outcome;

        var staged = new List<(string Temp, string Final, string Original)>();

        // Phase 1: original -> temporary.
        foreach (var item in work)
        {
            var source = Path.Combine(directory, item.Original);
            var temp = Path.Combine(directory, UniqueTempName(directory));
            try
            {
                File.Move(source, temp);
                staged.Add((temp, Path.Combine(directory, item.Proposed), item.Original));
            }
            catch (Exception ex)
            {
                outcome.Errors.Add($"{item.Original}: {ex.Message}");
            }
        }

        // Phase 2: temporary -> final. A failure here leaves the file under its temp name, so it is
        // moved back to its original name rather than being lost.
        foreach (var (temp, final, original) in staged)
        {
            try
            {
                File.Move(temp, final);
                outcome.Journal.Records.Add(new RenameRecord(original, Path.GetFileName(final)));
            }
            catch (Exception ex)
            {
                outcome.Errors.Add($"{original}: {ex.Message}");
                TryRestore(temp, Path.Combine(directory, original), outcome);
            }
        }

        return outcome;
    }

    /// <summary>Reverses a journal, newest record first, using the same two-phase move.</summary>
    public static RenameOutcome Undo(RenameJournal journal)
    {
        var reversed = journal.Records
            .AsEnumerable()
            .Reverse()
            .Select(r => new PlanItem
            {
                Original = r.To,
                Proposed = r.From,
                Status = PlanStatus.Ok,
                Reason = string.Empty,
            });

        return Apply(journal.Directory, reversed);
    }

    private static void TryRestore(string temp, string original, RenameOutcome outcome)
    {
        try
        {
            File.Move(temp, original);
        }
        catch (Exception ex)
        {
            outcome.Errors.Add($"could not restore '{Path.GetFileName(original)}' (left as '{Path.GetFileName(temp)}'): {ex.Message}");
        }
    }

    private static string UniqueTempName(string directory)
    {
        while (true)
        {
            var candidate = TempMarker + Guid.NewGuid().ToString("N");
            if (!File.Exists(Path.Combine(directory, candidate))) return candidate;
        }
    }
}

