using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The executable is a WinExe so the GUI starts without a console window flashing. A WinExe launched
/// from a shell has no standard output of its own, so the summary line would go nowhere. When (and only
/// when) the process has no stdout handle at all, attach to the parent console and rebind Console.Out.
/// If the caller redirected stdout to a pipe or file, the inherited handle is already valid and is left
/// untouched.
/// </summary>
internal static class ConsoleBridge
{
    private const int AttachParentProcess = -1;
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int processId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);

    public static void EnsureAttached()
    {
        if (HasHandle(StdOutputHandle) && HasHandle(StdErrorHandle)) return;
        if (!AttachConsole(AttachParentProcess)) return;

        Console.SetOut(Writer(Console.OpenStandardOutput()));
        Console.SetError(Writer(Console.OpenStandardError()));
    }

    private static bool HasHandle(int which)
    {
        var handle = GetStdHandle(which);
        return handle != IntPtr.Zero && handle != new IntPtr(-1);
    }

    private static StreamWriter Writer(Stream stream) =>
        new(stream, new UTF8Encoding(false)) { AutoFlush = true };
}

