using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The headless planning mode:
/// <c>BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</c>
/// Exits 0 on success, writes UTF-8 without BOM, prints one summary line to stdout, renames nothing.
/// </summary>
internal static class PlanCommand
{
    public const int ExitSuccess = 0;
    public const int ExitUsage = 2;
    public const int ExitFailure = 3;

    public static int Run(string[] args)
    {
        string? dir = null, rulesPath = null, outPath = null;

        for (int i = 0; i < args.Length; i++)
        {
            switch (args[i].ToLowerInvariant())
            {
                case "--plan":
                    break;
                case "--dir":
                    if (!TryTake(args, ref i, out dir)) return Usage("--dir requires a value");
                    break;
                case "--rules":
                    if (!TryTake(args, ref i, out rulesPath)) return Usage("--rules requires a value");
                    break;
                case "--out":
                    if (!TryTake(args, ref i, out outPath)) return Usage("--out requires a value");
                    break;
                default:
                    return Usage($"unknown argument '{args[i]}'");
            }
        }

        if (string.IsNullOrWhiteSpace(dir)) return Usage("--dir is required");
        if (string.IsNullOrWhiteSpace(rulesPath)) return Usage("--rules is required");
        if (string.IsNullOrWhiteSpace(outPath)) return Usage("--out is required");

        try
        {
            var fullDir = Path.GetFullPath(dir);
            if (!Directory.Exists(fullDir))
            {
                Console.Error.WriteLine($"error: folder not found: {fullDir}");
                return ExitFailure;
            }

            var rules = RulesJson.Load(Path.GetFullPath(rulesPath));
            var plan = PlanBuilder.Build(fullDir, rules);
            PlanJson.Write(Path.GetFullPath(outPath), plan);

            var s = plan.Summary;
            Console.Out.WriteLine(string.Format(
                CultureInfo.InvariantCulture,
                "planned {0} file(s): ok={1} collision={2} unchanged={3} invalid={4} -> {5}",
                s.Total, s.Ok, s.Collision, s.Unchanged, s.Invalid, Path.GetFullPath(outPath)));
            Console.Out.Flush();
            return ExitSuccess;
        }
        catch (RulesFormatException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitFailure;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return ExitFailure;
        }
    }

    private static bool TryTake(string[] args, ref int i, out string? value)
    {
        if (i + 1 >= args.Length)
        {
            value = null;
            return false;
        }

        value = args[++i];
        return true;
    }

    private static int Usage(string message)
    {
        Console.Error.WriteLine($"error: {message}");
        Console.Error.WriteLine(
            "usage: BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>");
        return ExitUsage;
    }
}

