using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Modal editor for a single step. One panel per op is built up front and only the panel matching the
/// selected op is shown, which keeps the dialog free of dynamic layout code.
/// </summary>
internal sealed class StepEditorForm : Form
{
    private readonly ComboBox _op = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 220 };
    private readonly Panel _host = new() { Dock = DockStyle.Fill };
    private readonly Dictionary<string, Panel> _panels = new(StringComparer.Ordinal);

    // replace
    private readonly TextBox _find = new();
    private readonly TextBox _replaceWith = new();
    private readonly CheckBox _regex = new() { Text = "規則運算式 (regex)", AutoSize = true };
    private readonly CheckBox _ignoreCase = new() { Text = "忽略大小寫 (ignore case)", AutoSize = true };

    // insert
    private readonly TextBox _insertText = new();
    private readonly ComboBox _insertPosition = new() { DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly NumericUpDown _insertIndex = new() { Minimum = 0, Maximum = 4096 };

    // remove
    private readonly NumericUpDown _removeFrom = new() { Minimum = 0, Maximum = 4096 };
    private readonly NumericUpDown _removeCount = new() { Minimum = 0, Maximum = 4096 };

    // sequence
    private readonly TextBox _pattern = new();
    private readonly NumericUpDown _start = new() { Minimum = -1_000_000, Maximum = 1_000_000 };
    private readonly NumericUpDown _increment = new() { Minimum = -1_000_000, Maximum = 1_000_000 };
    private readonly ComboBox _sequencePosition = new() { DropDownStyle = ComboBoxStyle.DropDownList };

    // case
    private readonly ComboBox _caseMode = new() { DropDownStyle = ComboBoxStyle.DropDownList };

    // extension
    private readonly ComboBox _extensionMode = new() { DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly TextBox _extensionValue = new();

    /// <summary>The edited step; only meaningful when the dialog returns <see cref="DialogResult.OK"/>.</summary>
    public Step? Result { get; private set; }

    public StepEditorForm(Step? existing)
    {
