                _sequencePosition.SelectedIndex = (int)s.Position;
                break;
            case CaseStep s:
                _op.SelectedIndex = 4;
                _caseMode.SelectedIndex = (int)s.Mode;
                break;
            case ExtensionStep s:
                _op.SelectedIndex = 5;
                _extensionMode.SelectedIndex = (int)s.Mode;
                _extensionValue.Text = s.Value;
                break;
            default:
                _op.SelectedIndex = 0;
                break;
        }

        ShowPanel();
    }

    private void Commit() => Result = SelectedOp switch
    {
        "insert" => new InsertStep
        {
            Text = _insertText.Text,
            Position = (InsertPosition)Math.Max(0, _insertPosition.SelectedIndex),
            Index = (int)_insertIndex.Value,
        },
        "remove" => new RemoveStep { From = (int)_removeFrom.Value, Count = (int)_removeCount.Value },
        "sequence" => new SequenceStep
        {
            Pattern = _pattern.Text,
            Start = (int)_start.Value,
            Increment = (int)_increment.Value,
            Position = (SequencePosition)Math.Max(0, _sequencePosition.SelectedIndex),
        },
        "case" => new CaseStep { Mode = (CaseMode)Math.Max(0, _caseMode.SelectedIndex) },
        "extension" => new ExtensionStep
        {
            Mode = (ExtensionMode)Math.Max(0, _extensionMode.SelectedIndex),
            Value = _extensionValue.Text,
        },
        _ => new ReplaceStep
        {
            Find = _find.Text,
            ReplaceWith = _replaceWith.Text,
            Regex = _regex.Checked,
            IgnoreCase = _ignoreCase.Checked,
        },
    };
}

