using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: pick a folder, stack up rule steps, watch the live preview, apply, undo.
/// The preview is produced by exactly the same <see cref="PlanBuilder"/> the headless mode uses, so what
/// the window shows and what <c>--plan</c> writes can never drift apart.
/// </summary>
internal sealed class MainForm : Form
{
    private readonly RuleSet _rules = new();
    private readonly Stack<RenameJournal> _undoStack = new();

    private readonly TextBox _folder = new() { Dock = DockStyle.Fill, ReadOnly = true };
    private readonly ComboBox _applyTo = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 220 };
    private readonly ComboBox _sort = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 180 };
    private readonly ListBox _steps = new() { Dock = DockStyle.Fill, IntegralHeight = false };
    private readonly DataGridView _preview = new();
    private readonly Label _summary = new() { Dock = DockStyle.Fill, TextAlign = ContentAlignment.MiddleLeft };
    private readonly Label _status = new() { Dock = DockStyle.Fill, TextAlign = ContentAlignment.MiddleLeft };
    private readonly Button _apply = new() { Text = "套用重新命名", Width = 140, Height = 30, Enabled = false };
    private readonly Button _undo = new() { Text = "復原上一次", Width = 120, Height = 30, Enabled = false };

    private static readonly Color OkColor = Color.FromArgb(232, 246, 233);
    private static readonly Color CollisionColor = Color.FromArgb(255, 243, 224);
    private static readonly Color InvalidColor = Color.FromArgb(253, 231, 231);
    private static readonly Color UnchangedColor = Color.FromArgb(245, 245, 245);

    public MainForm()
    {
        Text = "Batch Rename Studio";
        ClientSize = new Size(1120, 680);
        MinimumSize = new Size(920, 560);
        StartPosition = FormStartPosition.CenterScreen;
        Font = new Font("Microsoft JhengHei UI", 9f);

        Controls.Add(BuildBody());
        Controls.Add(BuildHeader());
        Controls.Add(BuildFooter());

        _applyTo.Items.AddRange(new object[] { "name — 只改主檔名", "nameAndExtension — 含副檔名" });
        _applyTo.SelectedIndex = 0;
        _applyTo.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = (ApplyTo)_applyTo.SelectedIndex;
            RefreshPreview();
        };

        _sort.Items.AddRange(new object[] { "name — 檔名", "created — 建立時間", "modified — 修改時間" });
        _sort.SelectedIndex = 0;
        _sort.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = (SortMode)_sort.SelectedIndex;
            RefreshPreview();
        };

        SetStatus("選擇資料夾後即可開始建立規則。");
    }

    private Control BuildHeader()
    {
        var header = new Panel { Dock = DockStyle.Top, Height = 86, Padding = new Padding(10, 8, 10, 4) };

        var row1 = new TableLayoutPanel { Dock = DockStyle.Top, Height = 34, ColumnCount = 4 };
        row1.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 90));
        row1.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        row1.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 110));
        row1.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 110));

        var browse = new Button { Text = "選擇資料夾…", Dock = DockStyle.Fill };
        browse.Click += (_, _) => ChooseFolder();
        var rescan = new Button { Text = "重新掃描", Dock = DockStyle.Fill };
        rescan.Click += (_, _) => RefreshPreview();

        row1.Controls.Add(new Label { Text = "資料夾", AutoSize = true, Anchor = AnchorStyles.Left, Margin = new Padding(3, 8, 3, 3) });
        row1.Controls.Add(_folder);
        row1.Controls.Add(browse);
        row1.Controls.Add(rescan);

        var row2 = new FlowLayoutPanel { Dock = DockStyle.Top, Height = 40, Padding = new Padding(0, 6, 0, 0) };
        row2.Controls.Add(new Label { Text = "套用對象 (applyTo)", AutoSize = true, Margin = new Padding(3, 8, 3, 3) });
        row2.Controls.Add(_applyTo);
        row2.Controls.Add(new Label { Text = "處理順序 (sort)", AutoSize = true, Margin = new Padding(20, 8, 3, 3) });
        row2.Controls.Add(_sort);

        header.Controls.Add(row2);
        header.Controls.Add(row1);
        return header;
    }

    private Control BuildBody()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            SplitterDistance = 380,
            FixedPanel = FixedPanel.Panel1,
        };

        // Left: the rule stack.
        var left = new Panel { Dock = DockStyle.Fill, Padding = new Padding(10, 4, 5, 4) };
        var stepButtons = new FlowLayoutPanel { Dock = DockStyle.Bottom, Height = 76, Padding = new Padding(0, 4, 0, 0) };

        stepButtons.Controls.Add(MakeButton("新增…", AddStep, 78));
        stepButtons.Controls.Add(MakeButton("編輯…", EditStep, 78));
        stepButtons.Controls.Add(MakeButton("刪除", RemoveStep, 68));
        stepButtons.Controls.Add(MakeButton("上移", () => MoveStep(-1), 68));
        stepButtons.Controls.Add(MakeButton("下移", () => MoveStep(1), 68));
        stepButtons.Controls.Add(MakeButton("載入規則…", LoadRules, 96));
        stepButtons.Controls.Add(MakeButton("儲存規則…", SaveRules, 96));
        stepButtons.Controls.Add(MakeButton("匯出計畫…", ExportPlan, 96));

        _steps.DoubleClick += (_, _) => EditStep();
        left.Controls.Add(_steps);
        left.Controls.Add(stepButtons);
        left.Controls.Add(new Label { Dock = DockStyle.Top, Height = 24, Text = "規則步驟 (steps) — 由上而下依序套用" });

        // Right: the preview table.
        var right = new Panel { Dock = DockStyle.Fill, Padding = new Padding(5, 4, 10, 4) };
        ConfigurePreview();
        right.Controls.Add(_preview);
        right.Controls.Add(new Panel { Dock = DockStyle.Bottom, Height = 26, Controls = { _summary } });
        right.Controls.Add(new Label { Dock = DockStyle.Top, Height = 24, Text = "預覽 (preview)" });

        split.Panel1.Controls.Add(left);
        split.Panel2.Controls.Add(right);
        return split;
    }

    private void ConfigurePreview()
    {
        _preview.Dock = DockStyle.Fill;
        _preview.AllowUserToAddRows = false;
        _preview.AllowUserToDeleteRows = false;
        _preview.ReadOnly = true;
        _preview.RowHeadersVisible = false;
        _preview.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        _preview.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;
        _preview.Columns.Add(NewColumn("original", "原始名稱", 34));
        _preview.Columns.Add(NewColumn("proposed", "建議名稱", 34));
        _preview.Columns.Add(NewColumn("status", "狀態", 12));
        _preview.Columns.Add(NewColumn("reason", "說明", 20));
    }

    private static DataGridViewTextBoxColumn NewColumn(string name, string header, int weight) => new()
    {
        Name = name,
        HeaderText = header,
        FillWeight = weight,
        SortMode = DataGridViewColumnSortMode.NotSortable,
    };

    private Control BuildFooter()
    {
        var footer = new Panel { Dock = DockStyle.Bottom, Height = 44, Padding = new Padding(10, 6, 10, 6) };
        var buttons = new FlowLayoutPanel { Dock = DockStyle.Right, FlowDirection = FlowDirection.RightToLeft, Width = 290 };

        _apply.Click += (_, _) => ApplyRenames();
        _undo.Click += (_, _) => UndoLast();
        buttons.Controls.Add(_apply);
        buttons.Controls.Add(_undo);

        footer.Controls.Add(_status);
        footer.Controls.Add(buttons);
        return footer;
    }

    private static Button MakeButton(string text, Action onClick, int width)
    {
        var button = new Button { Text = text, Width = width, Height = 30, Margin = new Padding(0, 3, 4, 3) };
        button.Click += (_, _) => onClick();
        return button;
    }

    // ---- rule stack -------------------------------------------------------

    private void AddStep()
    {
        using var dialog = new StepEditorForm(null);
        if (dialog.ShowDialog(this) == DialogResult.OK && dialog.Result is not null)
        {
            _rules.Steps.Add(dialog.Result);
            ReloadSteps(_rules.Steps.Count - 1);
        }
    }

    private void EditStep()
    {
        int index = _steps.SelectedIndex;
        if (index < 0) return;

        using var dialog = new StepEditorForm(_rules.Steps[index]);
        if (dialog.ShowDialog(this) == DialogResult.OK && dialog.Result is not null)
        {
            _rules.Steps[index] = dialog.Result;
            ReloadSteps(index);
        }
    }

    private void RemoveStep()
    {
        int index = _steps.SelectedIndex;
        if (index < 0) return;
        _rules.Steps.RemoveAt(index);
        ReloadSteps(Math.Min(index, _rules.Steps.Count - 1));
    }

    private void MoveStep(int delta)
    {
        int index = _steps.SelectedIndex;
        int target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count) return;

        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        ReloadSteps(target);
    }

    private void ReloadSteps(int select)
    {
        _steps.BeginUpdate();
        _steps.Items.Clear();
        for (int i = 0; i < _rules.Steps.Count; i++)
            _steps.Items.Add($"{i + 1}. {_rules.Steps[i].Describe()}");
        _steps.EndUpdate();

        if (select >= 0 && select < _steps.Items.Count) _steps.SelectedIndex = select;
        RefreshPreview();
    }

    // ---- folder, preview --------------------------------------------------

    private void ChooseFolder()
    {
        using var dialog = new FolderBrowserDialog { Description = "選擇要處理的資料夾", ShowNewFolderButton = false };
        if (!string.IsNullOrEmpty(_folder.Text)) dialog.SelectedPath = _folder.Text;
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        _folder.Text = dialog.SelectedPath;
        _undoStack.Clear();
        _undo.Enabled = false;
        RefreshPreview();
    }

    private RenamePlan? _plan;

    private void RefreshPreview()
    {
        _preview.Rows.Clear();
        _plan = null;
        _apply.Enabled = false;

        if (string.IsNullOrWhiteSpace(_folder.Text))
        {
            _summary.Text = string.Empty;
            return;
        }

        try
        {
            _plan = PlanBuilder.Build(_folder.Text, _rules);
        }
        catch (Exception ex)
        {
            _summary.Text = string.Empty;
            SetStatus($"無法建立計畫：{ex.Message}", error: true);
            return;
        }

        foreach (var item in _plan.Items)
        {
            int row = _preview.Rows.Add(item.Original, item.Proposed, item.Status, item.Reason);
            _preview.Rows[row].DefaultCellStyle.BackColor = item.Status switch
            {
                PlanStatus.Ok => OkColor,
                PlanStatus.Collision => CollisionColor,
                PlanStatus.Invalid => InvalidColor,
                _ => UnchangedColor,
            };
        }

        var s = _plan.Summary;
        _summary.Text = $"共 {s.Total} 個檔案 — 可套用 {s.Ok}、名稱衝突 {s.Collision}、未變更 {s.Unchanged}、不合法 {s.Invalid}";
        _apply.Enabled = s.Ok > 0;
        SetStatus(s.Ok > 0 ? "預覽已更新，可以套用。" : "沒有可套用的項目。");
    }

    // ---- apply / undo -----------------------------------------------------

    private void ApplyRenames()
    {
        if (_plan is null) return;

        var s = _plan.Summary;
        var warning = s.Collision + s.Invalid > 0
            ? $"\n\n（{s.Collision + s.Invalid} 個項目因衝突或名稱不合法會被略過）"
            : string.Empty;

        if (MessageBox.Show(this, $"即將重新命名 {s.Ok} 個檔案。{warning}", "確認套用",
                MessageBoxButtons.OKCancel, MessageBoxIcon.Question) != DialogResult.OK)
            return;

        var outcome = RenameExecutor.Apply(_folder.Text, _plan.Items);
        if (outcome.RenamedCount > 0)
        {
            _undoStack.Push(outcome.Journal);
            _undo.Enabled = true;
        }

        RefreshPreview();
        ReportOutcome(outcome, $"已重新命名 {outcome.RenamedCount} 個檔案。");
    }

    private void UndoLast()
    {
        if (_undoStack.Count == 0) return;

        var journal = _undoStack.Pop();
        var outcome = RenameExecutor.Undo(journal);
        _undo.Enabled = _undoStack.Count > 0;

        RefreshPreview();
        ReportOutcome(outcome, $"已復原 {outcome.RenamedCount} 個檔案。");
    }

    private void ReportOutcome(RenameOutcome outcome, string successText)
    {
        if (outcome.Errors.Count == 0)
        {
            SetStatus(successText);
            return;
        }

        SetStatus($"{successText} 有 {outcome.Errors.Count} 個項目失敗。", error: true);
        MessageBox.Show(this, string.Join(Environment.NewLine, outcome.Errors.Take(20)),
            "部分項目失敗", MessageBoxButtons.OK, MessageBoxIcon.Warning);
    }

    // ---- rules and plan files --------------------------------------------

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog { Filter = "規則檔 (*.json)|*.json|所有檔案 (*.*)|*.*" };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            var loaded = RulesJson.Load(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            _applyTo.SelectedIndex = (int)_rules.ApplyTo;
            _sort.SelectedIndex = (int)_rules.Sort;
            ReloadSteps(_rules.Steps.Count > 0 ? 0 : -1);
            SetStatus($"已載入規則：{dialog.FileName}");
        }
        catch (Exception ex)
        {
            SetStatus($"載入失敗：{ex.Message}", error: true);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog { Filter = "規則檔 (*.json)|*.json", FileName = "rules.json" };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            RulesJson.Save(dialog.FileName, _rules);
            SetStatus($"已儲存規則：{dialog.FileName}");
        }
        catch (Exception ex)
        {
            SetStatus($"儲存失敗：{ex.Message}", error: true);
        }
    }

    private void ExportPlan()
    {
        if (_plan is null)
        {
            SetStatus("目前沒有可匯出的計畫。", error: true);
            return;
        }

        using var dialog = new SaveFileDialog { Filter = "計畫檔 (*.json)|*.json", FileName = "plan.json" };
        if (dialog.ShowDialog(this) != DialogResult.OK) return;

        try
        {
            PlanJson.Write(dialog.FileName, _plan);
            SetStatus($"已匯出計畫：{dialog.FileName}");
        }
        catch (Exception ex)
        {
            SetStatus($"匯出失敗：{ex.Message}", error: true);
        }
    }

    private void SetStatus(string text, bool error = false)
    {
        _status.Text = text;
        _status.ForeColor = error ? Color.Firebrick : SystemColors.ControlText;
    }
}

