using System.Text;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Thrown when rules.json does not describe a usable rule set.</summary>
public sealed class RulesFormatException : Exception
{
    public RulesFormatException(string message) : base(message) { }
}

/// <summary>Reader/writer for the rules.json contract. Hand written so the contract stays explicit.</summary>
public static class RulesJson
{
    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path, Encoding.UTF8);
        }
        catch (Exception ex)
        {
            throw new RulesFormatException($"cannot read rules file '{path}': {ex.Message}");
        }

        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, new JsonDocumentOptions
            {
                AllowTrailingCommas = true,
                CommentHandling = JsonCommentHandling.Skip,
            });
        }
        catch (JsonException ex)
        {
            throw new RulesFormatException($"rules file is not valid JSON: {ex.Message}");
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
                throw new RulesFormatException("rules file must contain a JSON object at the root");

            var rules = new RuleSet
            {
                ApplyTo = ParseApplyTo(GetString(root, "applyTo", "name")),
                Sort = ParseSort(GetString(root, "sort", "name")),
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                    throw new RulesFormatException("'steps' must be an array");

                int i = 0;
                foreach (var element in steps.EnumerateArray())
                {
                    rules.Steps.Add(ParseStep(element, i));
                    i++;
                }
            }

            return rules;
        }
    }

    public static string Serialize(RuleSet rules)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true }))
        {
            writer.WriteStartObject();
            writer.WriteString("applyTo", rules.ApplyTo == ApplyTo.Name ? "name" : "nameAndExtension");
            writer.WriteString("sort", rules.Sort.ToString().ToLowerInvariant());
            writer.WriteStartArray("steps");
            foreach (var step in rules.Steps) WriteStep(writer, step);
            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        return JsonText.Normalize(stream.ToArray());
    }

    public static void Save(string path, RuleSet rules) =>
        JsonText.WriteUtf8NoBom(path, Serialize(rules));

    private static void WriteStep(Utf8JsonWriter w, Step step)
    {
        w.WriteStartObject();
        w.WriteString("op", step.Op);
        switch (step)
        {
            case ReplaceStep s:
                w.WriteString("find", s.Find);
                w.WriteString("replaceWith", s.ReplaceWith);
                w.WriteBoolean("regex", s.Regex);
                w.WriteBoolean("ignoreCase", s.IgnoreCase);
                break;
            case InsertStep s:
                w.WriteString("text", s.Text);
                w.WriteString("position", s.Position.ToString().ToLowerInvariant());
                w.WriteNumber("index", s.Index);
                break;
            case RemoveStep s:
                w.WriteNumber("from", s.From);
                w.WriteNumber("count", s.Count);
                break;
            case SequenceStep s:
                w.WriteString("pattern", s.Pattern);
                w.WriteNumber("start", s.Start);
                w.WriteNumber("step", s.Increment);
                w.WriteString("position", s.Position.ToString().ToLowerInvariant());
                break;
            case CaseStep s:
                w.WriteString("mode", s.Mode.ToString().ToLowerInvariant());
                break;
            case ExtensionStep s:
                w.WriteString("mode", s.Mode.ToString().ToLowerInvariant());
                if (s.Mode == ExtensionMode.Set) w.WriteString("value", s.Value);
                break;
        }

        w.WriteEndObject();
    }

    private static Step ParseStep(JsonElement e, int index)
    {
        if (e.ValueKind != JsonValueKind.Object)
            throw new RulesFormatException($"steps[{index}] must be an object");

        var op = GetString(e, "op", string.Empty).ToLowerInvariant();
        switch (op)
        {
            case "replace":
                return new ReplaceStep
                {
                    Find = GetString(e, "find", string.Empty),
                    ReplaceWith = GetString(e, "replaceWith", string.Empty),
                    Regex = GetBool(e, "regex", false),
                    IgnoreCase = GetBool(e, "ignoreCase", false),
                };
            case "insert":
                return new InsertStep
                {
                    Text = GetString(e, "text", string.Empty),
                    Position = GetString(e, "position", "prefix").ToLowerInvariant() switch
                    {
                        "prefix" => InsertPosition.Prefix,
                        "suffix" => InsertPosition.Suffix,
                        "index" => InsertPosition.Index,
                        var other => throw new RulesFormatException($"steps[{index}]: unknown insert position '{other}'"),
                    },
                    Index = GetInt(e, "index", 0),
                };
            case "remove":
                return new RemoveStep
                {
                    From = GetInt(e, "from", 0),
                    Count = GetInt(e, "count", 0),
                };
            case "sequence":
                return new SequenceStep
                {
                    Pattern = GetString(e, "pattern", "{n:000}"),
                    Start = GetInt(e, "start", 1),
                    Increment = GetInt(e, "step", 1),
                    Position = GetString(e, "position", "prefix").ToLowerInvariant() switch
                    {
                        "prefix" => SequencePosition.Prefix,
                        "suffix" => SequencePosition.Suffix,
                        var other => throw new RulesFormatException($"steps[{index}]: unknown sequence position '{other}'"),
                    },
                };
            case "case":
                return new CaseStep
                {
                    Mode = GetString(e, "mode", "lower").ToLowerInvariant() switch
                    {
                        "upper" => CaseMode.Upper,
                        "lower" => CaseMode.Lower,
                        "title" => CaseMode.Title,
                        var other => throw new RulesFormatException($"steps[{index}]: unknown case mode '{other}'"),
                    },
                };
            case "extension":
                return new ExtensionStep
                {
                    Mode = GetString(e, "mode", "lower").ToLowerInvariant() switch
                    {
                        "lower" => ExtensionMode.Lower,
                        "upper" => ExtensionMode.Upper,
                        "set" => ExtensionMode.Set,
                        var other => throw new RulesFormatException($"steps[{index}]: unknown extension mode '{other}'"),
                    },
                    Value = GetString(e, "value", string.Empty),
                };
            case "":
                throw new RulesFormatException($"steps[{index}] is missing the 'op' property");
            default:
                throw new RulesFormatException($"steps[{index}]: unknown op '{op}'");
        }
    }

    private static ApplyTo ParseApplyTo(string value) => value.ToLowerInvariant() switch
    {
        "name" => ApplyTo.Name,
        "nameandextension" => ApplyTo.NameAndExtension,
        _ => throw new RulesFormatException($"unknown applyTo value '{value}'"),
    };

    private static SortMode ParseSort(string value) => value.ToLowerInvariant() switch
    {
        "name" => SortMode.Name,
        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        _ => throw new RulesFormatException($"unknown sort value '{value}'"),
    };

    private static string GetString(JsonElement e, string name, string fallback)
    {
        if (!e.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null) return fallback;
        if (v.ValueKind != JsonValueKind.String)
            throw new RulesFormatException($"'{name}' must be a string");
        return v.GetString() ?? fallback;
    }

    private static bool GetBool(JsonElement e, string name, bool fallback)
    {
        if (!e.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null) return fallback;
        return v.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            _ => throw new RulesFormatException($"'{name}' must be a boolean"),
        };
    }

    private static int GetInt(JsonElement e, string name, int fallback)
    {
        if (!e.TryGetProperty(name, out var v) || v.ValueKind == JsonValueKind.Null) return fallback;
        if (v.ValueKind != JsonValueKind.Number || !v.TryGetInt32(out var n))
            throw new RulesFormatException($"'{name}' must be a 32-bit integer");
        return n;
    }
}

using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>A file name split into base and extension per rule 2 of the contract (the extension excludes the dot).</summary>
public readonly record struct SplitName(string Base, string Extension)
{
    /// <summary>Rule 2: split at the LAST dot, but only when that dot is not the first character.</summary>
    public static SplitName Split(string fileName)
    {
        int dot = fileName.LastIndexOf('.');
        return dot > 0
            ? new SplitName(fileName[..dot], fileName[(dot + 1)..])
            : new SplitName(fileName, string.Empty);
    }

    /// <summary>Rule 12: base + "." + ext when the extension is non-empty, otherwise base alone.</summary>
    public string Join() => Extension.Length > 0 ? Base + "." + Extension : Base;
}

/// <summary>Applies a rule set to a single file name. Pure: no file system access, no shared state.</summary>
public static class NameTransformer
{
    /// <param name="fileName">The original file name (no directory part).</param>
    /// <param name="ordinal">0-based position of this file in processing order; drives the sequence counter.</param>
    public static string Apply(RuleSet rules, string fileName, int ordinal)
    {
        var split = SplitName.Split(fileName);

        if (rules.ApplyTo == ApplyTo.Name)
        {
            // The steps see the base only; an extension step edits the separate extension slot.
            var target = split.Base;
            var extension = split.Extension;
            foreach (var step in rules.Steps)
            {
                if (step is ExtensionStep ext) extension = ApplyExtension(ext, extension);
                else target = ApplyToTarget(step, target, ordinal);
            }

            return new SplitName(target, extension).Join();
        }

        // nameAndExtension: the target string IS the whole name; an extension step re-splits the
        // current string and edits its trailing extension (rule 12).
        var whole = fileName;
        foreach (var step in rules.Steps)
        {
            if (step is ExtensionStep ext)
            {
                var current = SplitName.Split(whole);
                whole = new SplitName(current.Base, ApplyExtension(ext, current.Extension)).Join();
            }
            else
            {
                whole = ApplyToTarget(step, whole, ordinal);
            }
        }

        return whole;
    }

    private static string ApplyToTarget(Step step, string target, int ordinal) => step switch
    {
        ReplaceStep s => ApplyReplace(s, target),
        InsertStep s => ApplyInsert(s, target),
        RemoveStep s => ApplyRemove(s, target),
        SequenceStep s => ApplySequence(s, target, ordinal),
        CaseStep s => ApplyCase(s, target),
        _ => target,
    };

    private static string ApplyReplace(ReplaceStep s, string target)
    {
        if (s.Regex)
        {
            var options = RegexOptions.CultureInvariant;
            if (s.IgnoreCase) options |= RegexOptions.IgnoreCase;
            return Regex.Replace(target, s.Find, s.ReplaceWith, options);
        }

        // String.Replace rejects an empty needle; treat it as a no-op instead of failing the run.
        if (s.Find.Length == 0) return target;
        return target.Replace(s.Find, s.ReplaceWith,
            s.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal);
    }

    private static string ApplyInsert(InsertStep s, string target) => s.Position switch
    {
        InsertPosition.Prefix => s.Text + target,
        InsertPosition.Suffix => target + s.Text,
        _ => target.Insert(Math.Clamp(s.Index, 0, target.Length), s.Text),
    };

    private static string ApplyRemove(RemoveStep s, string target)
    {
        int from = Math.Clamp(s.From, 0, target.Length);
        int count = Math.Clamp(s.Count, 0, target.Length - from);
        return count == 0 ? target : target.Remove(from, count);
    }

    private static string ApplySequence(SequenceStep s, string target, int ordinal)
    {
        long counter = (long)s.Start + (long)s.Increment * ordinal;
        var rendered = RenderSequence(s.Pattern, counter);
        return s.Position == SequencePosition.Prefix ? rendered + target : target + rendered;
    }

    private static readonly Regex SequenceToken = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    /// <summary>Rule 9: literal text plus exactly one {n:PAD} token, PAD giving the zero-pad width.</summary>
    public static string RenderSequence(string pattern, long counter)
    {
        var match = SequenceToken.Match(pattern);
        if (!match.Success) return pattern;

        int width = match.Groups[1].Value.Length;
        var number = counter.ToString(new string('0', width), CultureInfo.InvariantCulture);
        return pattern[..match.Index] + number + pattern[(match.Index + match.Length)..];
    }

    private static string ApplyCase(CaseStep s, string target) => s.Mode switch
    {
        CaseMode.Upper => target.ToUpperInvariant(),
        CaseMode.Lower => target.ToLowerInvariant(),
        _ => ToTitleCase(target),
    };

    /// <summary>Rule 10: in every maximal run of Unicode letters, the first char goes upper, the rest lower.</summary>
    public static string ToTitleCase(string value)
    {
        var sb = new StringBuilder(value.Length);
        bool inLetterRun = false;
        foreach (var ch in value)
        {
            if (char.IsLetter(ch))
            {
                sb.Append(inLetterRun ? char.ToLowerInvariant(ch) : char.ToUpperInvariant(ch));
                inLetterRun = true;
            }
            else
            {
                sb.Append(ch);
                inLetterRun = false;
            }
        }

        return sb.ToString();
    }

    private static string ApplyExtension(ExtensionStep s, string extension) => s.Mode switch
    {
        ExtensionMode.Lower => extension.ToLowerInvariant(),
        ExtensionMode.Upper => extension.ToUpperInvariant(),
        _ => s.Value,
    };

    /// <summary>Validates every regex in the rule set up front, so a bad pattern fails loudly instead of per file.</summary>
    public static void ValidateRegexes(RuleSet rules)
    {
        for (int i = 0; i < rules.Steps.Count; i++)
        {
            if (rules.Steps[i] is not ReplaceStep { Regex: true } s) continue;
            try
            {
                _ = new Regex(s.Find, RegexOptions.CultureInvariant);
            }
            catch (ArgumentException ex)
            {
                throw new RulesFormatException($"steps[{i}]: invalid regex '{s.Find}': {ex.Message}");
            }
        }
    }
}

using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Modal editor for a single step. One panel per op is built up front and only the panel matching the
/// selected op is shown, which keeps the dialog free of dynamic layout code.
/// </summary>
internal sealed class StepEditorForm : Form
{
    private readonly ComboBox _op = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 220 };
    private readonly Panel _host = new() { Dock = DockStyle.Fill };
    private readonly Dictionary<string, Panel> _panels = new(StringComparer.Ordinal);

    // replace
    private readonly TextBox _find = new();
    private readonly TextBox _replaceWith = new();
    private readonly CheckBox _regex = new() { Text = "規則運算式 (regex)", AutoSize = true };
    private readonly CheckBox _ignoreCase = new() { Text = "忽略大小寫 (ignore case)", AutoSize = true };

    // insert
    private readonly TextBox _insertText = new();
    private readonly ComboBox _insertPosition = new() { DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly NumericUpDown _insertIndex = new() { Minimum = 0, Maximum = 4096 };

    // remove
    private readonly NumericUpDown _removeFrom = new() { Minimum = 0, Maximum = 4096 };
    private readonly NumericUpDown _removeCount = new() { Minimum = 0, Maximum = 4096 };

    // sequence
    private readonly TextBox _pattern = new();
    private readonly NumericUpDown _start = new() { Minimum = -1_000_000, Maximum = 1_000_000 };
    private readonly NumericUpDown _increment = new() { Minimum = -1_000_000, Maximum = 1_000_000 };
    private readonly ComboBox _sequencePosition = new() { DropDownStyle = ComboBoxStyle.DropDownList };

    // case
    private readonly ComboBox _caseMode = new() { DropDownStyle = ComboBoxStyle.DropDownList };

    // extension
    private readonly ComboBox _extensionMode = new() { DropDownStyle = ComboBoxStyle.DropDownList };
    private readonly TextBox _extensionValue = new();

    /// <summary>The edited step; only meaningful when the dialog returns <see cref="DialogResult.OK"/>.</summary>
    public Step? Result { get; private set; }

    public StepEditorForm(Step? existing)
    {
        Text = existing is null ? "新增步驟 (add step)" : "編輯步驟 (edit step)";
        StartPosition = FormStartPosition.CenterParent;
        FormBorderStyle = FormBorderStyle.FixedDialog;
        MinimizeBox = false;
        MaximizeBox = false;
        ClientSize = new Size(460, 260);
        Font = new Font("Microsoft JhengHei UI", 9f);

        _op.Items.AddRange(new object[]
        {
            "replace — 取代文字",
            "insert — 插入文字",
            "remove — 移除字元",
            "sequence — 流水號",
            "case — 大小寫",
            "extension — 副檔名",
        });

        var top = new Panel { Dock = DockStyle.Top, Height = 44, Padding = new Padding(12, 12, 12, 0) };
        var opLabel = new Label { Text = "操作 (op)", AutoSize = true, Location = new Point(12, 16) };
        _op.Location = new Point(90, 12);
        _op.SelectedIndexChanged += (_, _) => ShowPanel();
        top.Controls.Add(opLabel);
        top.Controls.Add(_op);

        _host.Padding = new Padding(12, 8, 12, 8);

        BuildPanels();

        var buttons = new FlowLayoutPanel
        {
            Dock = DockStyle.Bottom,
            FlowDirection = FlowDirection.RightToLeft,
            Height = 48,
            Padding = new Padding(12, 8, 12, 8),
        };
        var ok = new Button { Text = "確定", DialogResult = DialogResult.OK, Width = 90 };
        var cancel = new Button { Text = "取消", DialogResult = DialogResult.Cancel, Width = 90 };
        ok.Click += (_, _) => Commit();
        buttons.Controls.Add(ok);
        buttons.Controls.Add(cancel);
        AcceptButton = ok;
        CancelButton = cancel;

        Controls.Add(_host);
        Controls.Add(buttons);
        Controls.Add(top);

        Load(existing);
    }

    private void BuildPanels()
    {
        _insertPosition.Items.AddRange(new object[] { "prefix — 開頭", "suffix — 結尾", "index — 指定位置" });
        _sequencePosition.Items.AddRange(new object[] { "prefix — 開頭", "suffix — 結尾" });
        _caseMode.Items.AddRange(new object[] { "upper — 全大寫", "lower — 全小寫", "title — 首字大寫" });
        _extensionMode.Items.AddRange(new object[] { "lower — 轉小寫", "upper — 轉大寫", "set — 指定副檔名" });

        _panels["replace"] = Grid(
            ("尋找 (find)", _find),
            ("取代為 (replaceWith)", _replaceWith),
            (string.Empty, _regex),
            (string.Empty, _ignoreCase));

        _panels["insert"] = Grid(
            ("插入文字 (text)", _insertText),
            ("位置 (position)", _insertPosition),
            ("索引 (index)", _insertIndex));

        _panels["remove"] = Grid(
            ("起始索引 (from)", _removeFrom),
            ("字元數 (count)", _removeCount));

        _panels["sequence"] = Grid(
            ("樣式 (pattern)", _pattern),
            ("起始值 (start)", _start),
            ("遞增量 (step)", _increment),
            ("位置 (position)", _sequencePosition));

        _panels["case"] = Grid(("模式 (mode)", _caseMode));

        _panels["extension"] = Grid(
            ("模式 (mode)", _extensionMode),
            ("副檔名 (value，不含點)", _extensionValue));

        foreach (var panel in _panels.Values)
        {
            panel.Visible = false;
            _host.Controls.Add(panel);
        }
    }

    private static Panel Grid(params (string Label, Control Control)[] rows)
    {
        var table = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 2,
            RowCount = rows.Length + 1,
            AutoSize = false,
        };
        table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 170));
        table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));

        foreach (var (label, control) in rows)
        {
            table.RowStyles.Add(new RowStyle(SizeType.Absolute, 32));
            table.Controls.Add(new Label { Text = label, AutoSize = true, Anchor = AnchorStyles.Left, Margin = new Padding(3, 7, 3, 3) });
            control.Dock = control is CheckBox ? DockStyle.Left : DockStyle.Fill;
            control.Margin = new Padding(3, 4, 3, 3);
            table.Controls.Add(control);
        }

        table.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        return table;
    }

    private string SelectedOp => _op.SelectedIndex switch
    {
        0 => "replace",
        1 => "insert",
        2 => "remove",
        3 => "sequence",
        4 => "case",
        5 => "extension",
        _ => "replace",
    };

    private void ShowPanel()
    {
        foreach (var (op, panel) in _panels) panel.Visible = op == SelectedOp;
    }

    private void Load(Step? step)
    {
        _pattern.Text = "{n:000}_";
        _start.Value = 1;
        _increment.Value = 1;
        _insertPosition.SelectedIndex = 0;
        _sequencePosition.SelectedIndex = 0;
        _caseMode.SelectedIndex = 1;
        _extensionMode.SelectedIndex = 0;

        switch (step)
        {
            case ReplaceStep s:
                _op.SelectedIndex = 0;
                _find.Text = s.Find;
                _replaceWith.Text = s.ReplaceWith;
                _regex.Checked = s.Regex;
                _ignoreCase.Checked = s.IgnoreCase;
                break;
            case InsertStep s:
                _op.SelectedIndex = 1;
                _insertText.Text = s.Text;
                _insertPosition.SelectedIndex = (int)s.Position;
                _insertIndex.Value = Math.Clamp(s.Index, 0, 4096);
                break;
            case RemoveStep s:
                _op.SelectedIndex = 2;
                _removeFrom.Value = Math.Clamp(s.From, 0, 4096);
