using System.Runtime.InteropServices;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The executable is built for the console subsystem so that <c>--plan</c> behaves like a normal CLI:
/// shells wait for it, the exit code is observable and stdout is a real stream. When the GUI starts
/// instead, the console is dropped — and closed if this process is the one that owns it (started from
/// Explorer), while a console shared with a parent shell is only detached, never hidden.
/// </summary>
internal static class ConsoleWindow
{
    private const int SwHide = 0;

    [DllImport("kernel32.dll")]
    private static extern IntPtr GetConsoleWindow();

    [DllImport("kernel32.dll")]
    private static extern bool FreeConsole();

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint GetConsoleProcessList(uint[] processList, uint count);

    [DllImport("user32.dll")]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    public static void DetachForGui()
    {
        try
        {
            var window = GetConsoleWindow();
            if (window == IntPtr.Zero) return;

            var buffer = new uint[4];
            if (GetConsoleProcessList(buffer, (uint)buffer.Length) <= 1) ShowWindow(window, SwHide);
            FreeConsole();
        }
        catch (DllNotFoundException)
        {
            // Nothing to detach from; the GUI can start regardless.
        }
        catch (EntryPointNotFoundException)
        {
        }
    }
}

