using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        if (args.Any(a => string.Equals(a, "--plan", StringComparison.OrdinalIgnoreCase)))
            return PlanCommand.Run(args);

        if (args.Any(a => a is "--help" or "-h" or "/?"))
        {
            Console.Out.WriteLine(
                "usage: BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>");
            Console.Out.WriteLine("       BatchRenameStudio.exe                (starts the graphical interface)");
            return 0;
        }

        ConsoleWindow.DetachForGui();
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.SetHighDpiMode(HighDpiMode.SystemAware);
        Application.Run(new MainForm());
        return 0;
    }
}

