using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>
/// Persists a <see cref="RenameJournal"/> so an applied batch stays reversible after the process ends.
/// Same conventions as every other file this tool writes: UTF-8 without BOM, LF endings.
/// </summary>
public static class JournalJson
{
    public const int SchemaVersion = 1;

    public static string Serialize(RenameJournal journal)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, new JsonWriterOptions { Indented = true }))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", SchemaVersion);
            writer.WriteString("directory", journal.Directory);
            writer.WriteStartArray("renames");
            foreach (var record in journal.Records)
            {
                writer.WriteStartObject();
                writer.WriteString("from", record.From);
                writer.WriteString("to", record.To);
                writer.WriteEndObject();
            }

            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        return JsonText.Normalize(stream.ToArray()) + "\n";
    }

    public static void Write(string path, RenameJournal journal) =>
        JsonText.WriteUtf8NoBom(path, Serialize(journal));

    public static RenameJournal Load(string path)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var root = doc.RootElement;
        var journal = new RenameJournal
        {
            Directory = root.TryGetProperty("directory", out var d) ? d.GetString() ?? string.Empty : string.Empty,
        };

        if (root.TryGetProperty("renames", out var renames) && renames.ValueKind == JsonValueKind.Array)
        {
            foreach (var element in renames.EnumerateArray())
            {
                var from = element.TryGetProperty("from", out var f) ? f.GetString() : null;
                var to = element.TryGetProperty("to", out var t) ? t.GetString() : null;
                if (from is null || to is null) continue;
                journal.Records.Add(new RenameRecord(from, to));
            }
        }

        return journal;
    }

    /// <summary>Default location for GUI journals, so an applied batch survives a crash or a restart.</summary>
    public static string DefaultJournalPath(DateTime stampUtc)
    {
        var folder = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "BatchRenameStudio",
            "journals");
        return Path.Combine(folder, $"journal-{stampUtc:yyyyMMdd-HHmmss-fff}.json");
    }
}

