using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// Optional headless companions to <c>--plan</c>. These are outside the fixed plan contract and never
/// change its behaviour; they exist so the rename and undo paths can be exercised without the GUI.
/// <code>
/// --apply --dir &lt;folder&gt; --rules &lt;rules.json&gt; [--journal &lt;journal.json&gt;]
/// --undo  --journal &lt;journal.json&gt;
/// </code>
/// </summary>
internal static class ApplyCommand
{
    public static int RunApply(string[] args)
    {
        string? dir = null, rulesPath = null, journalPath = null;
        for (int i = 0; i < args.Length; i++)
        {
            switch (args[i].ToLowerInvariant())
            {
                case "--apply": break;
                case "--dir": dir = Next(args, ref i); break;
                case "--rules": rulesPath = Next(args, ref i); break;
                case "--journal": journalPath = Next(args, ref i); break;
                default: return Fail($"unknown argument '{args[i]}'", PlanCommand.ExitUsage);
            }
        }

        if (string.IsNullOrWhiteSpace(dir)) return Fail("--dir is required", PlanCommand.ExitUsage);
        if (string.IsNullOrWhiteSpace(rulesPath)) return Fail("--rules is required", PlanCommand.ExitUsage);

        try
        {
            var fullDir = Path.GetFullPath(dir);
            var rules = RulesJson.Load(Path.GetFullPath(rulesPath));
            var plan = PlanBuilder.Build(fullDir, rules);
            var outcome = RenameExecutor.Apply(fullDir, plan.Items);

            journalPath ??= JournalJson.DefaultJournalPath(DateTime.UtcNow);
            JournalJson.Write(Path.GetFullPath(journalPath), outcome.Journal);

            foreach (var error in outcome.Errors) Console.Error.WriteLine($"warning: {error}");

            Console.Out.WriteLine(string.Format(
                CultureInfo.InvariantCulture,
                "renamed {0} of {1} file(s), {2} failed -> journal {3}",
                outcome.RenamedCount, plan.Summary.Ok, outcome.Errors.Count, Path.GetFullPath(journalPath)));
            return outcome.Errors.Count == 0 ? PlanCommand.ExitSuccess : PlanCommand.ExitFailure;
        }
        catch (Exception ex)
        {
            return Fail(ex.Message, PlanCommand.ExitFailure);
        }
    }

    public static int RunUndo(string[] args)
    {
        string? journalPath = null;
        for (int i = 0; i < args.Length; i++)
        {
            switch (args[i].ToLowerInvariant())
            {
                case "--undo": break;
                case "--journal": journalPath = Next(args, ref i); break;
                default: return Fail($"unknown argument '{args[i]}'", PlanCommand.ExitUsage);
            }
        }

        if (string.IsNullOrWhiteSpace(journalPath)) return Fail("--journal is required", PlanCommand.ExitUsage);

        try
        {
            var journal = JournalJson.Load(Path.GetFullPath(journalPath));
            var outcome = RenameExecutor.Undo(journal);
            foreach (var error in outcome.Errors) Console.Error.WriteLine($"warning: {error}");

            Console.Out.WriteLine(string.Format(
                CultureInfo.InvariantCulture,
                "reverted {0} of {1} rename(s), {2} failed",
                outcome.RenamedCount, journal.Records.Count, outcome.Errors.Count));
            return outcome.Errors.Count == 0 ? PlanCommand.ExitSuccess : PlanCommand.ExitFailure;
        }
        catch (Exception ex)
        {
            return Fail(ex.Message, PlanCommand.ExitFailure);
        }
    }

    private static string? Next(string[] args, ref int i) => i + 1 < args.Length ? args[++i] : null;

    private static int Fail(string message, int code)
    {
        Console.Error.WriteLine($"error: {message}");
        return code;
    }
}

